pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposits) public {
        // restrict deposits to a plausible range to avoid overflow but keep wide
        vm.assume(deposits >= 1 && deposits <= 100);
        // fund deposits to create a balance
        for (uint i = 0; i < deposits; i++) {
            vm.deal(address(this), 1 ether);
            (bool ok, ) = address(c).call{value: 1 ether}("");
            // if fallback fails for any reason, skip this iteration (it succeeds for EOA)
            vm.assume(ok);
        }
        uint balanceBefore = address(c).balance;
        // execute withdrawAll as owner
        c.withdrawAll();
        uint balanceAfter = address(c).balance;
        // The reference withdraws the full balance, so balanceAfter = 0.
        // The mutant withdraws 0, so balanceAfter = balanceBefore.
        // A general rule: after withdrawAll by the owner, the new balance equals
        // the old balance minus the amount withdrawn (which for the reference is full balance,
        // for the mutant is 0). Equivalently:
        // If withdrawAll succeeded, balanceAfter must be 0 (reference) but mutant fails this.
        // However, the domain includes any number of deposits, and the rule must hold for ALL.
        // Universal property: address(c).balance after a successful withdrawAll by the owner is 0.
        // The mutant leaves balance unchanged -> nonzero when deposits > 0.
        assertTrue(balanceAfter == 0);
    }
}

