import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // 1. restrict domain to be wide but avoid overflow or zero-amount edge cases
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // 2. deposit ether from an EOA, making the contract have some balance
        address depositor = makeAddr("depositor");
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        (bool success,) = address(c).call{value: depositAmount}("");
        require(success, "deposit failed");

        uint256 balanceBefore = address(c).balance;
        assertGt(balanceBefore, 0);

        // deploy a reverter helper that causes any low-level call to fail
        Reverter reverter = new Reverter();

        // owner triggers sendMoney to a contract that always reverts, to rule out that the invariant holds trivially
        vm.prank(c.owner());
        c.sendMoney(address(reverter), withdrawAmount, "");

        // now call withdrawAll — it should drain the contract in the reference
        vm.prank(c.owner());
        c.withdrawAll();

        // 3. assertion: after withdrawAll(), contract balance must be exactly zero
        assertEq(address(c).balance, 0, "balance not zero after withdrawAll");
    }
}
contract Reverter {
    fallback() external payable { revert(); }
}

