contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 sendValue) public {
        // restrict amounts to avoid overflow/insufficient balance issues; keep it wide
        amount = bound(amount, 0, type(uint128).max);
