        vm.assume(amount + sendValue < type(uint128).max);

        // fund the owner and the contract
        address owner = c.owner();
        vm.deal(owner, amount);
        vm.deal(address(c), 0);

        // owner sends ether to the contract via low-level call to make the contract have balance
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        // owner calls sendMoney to trigger some external call; we use a simple EOA target
