        c.sendMoney(address(0xdead), sendValue, "");

        // after sendMoney, owner attempts to withdraw all remaining balance
        uint256 balBefore = address(c).balance;
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // The property: after any sendMoney, withdrawAll always succeeds and drains the contract.
        // The reference: transfer works, withdrawAll succeeds. Bug: withdraw reverts, withdrawAll always reverts.
